SET TERM ^;
CREATE PROCEDURE YC1 RETURNS (C INTEGER) AS DECLARE V VARCHAR(10) CHARACTER SET UTF8 COLLATE UCS_BASIC = 'é'; BEGIN C = 0; IF (V = 'é') THEN C = 1; SUSPEND; C = 0; IF (V = 'É') THEN C = 1; SUSPEND; END^
