CREATE PROCEDURE YC4 RETURNS (C INTEGER) AS DECLARE V DRCI = 'é'; BEGIN C = 0; IF (V = 'É') THEN C = 1; SUSPEND; SELECT COUNT(*) FROM RC WHERE U = :V INTO C; SUSPEND; END^
