pin  "12c [UTF8] REPLACE(U COLLATE UNICODE_CI, 'b', 'c') = 'AC': the search runs under the collation (it counted 1, 723ca57 refused)" $'SELECT COUNT(*) AS C FROM RC WHERE REPLACE(U COLLATE UNICODE_CI, \'b\', \'c\') = \'AC\';' $'C|2'
